export interface D5OsmBuilderData {
  translations?: Record<string, string>;
  cptTypes?: Record<string, string>;
  cptTaxonomies?: Record<string, string>;
  cptPreview?: { url?: string; nonce?: string };
}

declare global {
  interface Window {
    D5ModuleOpenstreetmapBuilderBundleScriptData?: D5OsmBuilderData;
  }
}

/**
 * Data handed to our bundle inside the Visual Builder's app window via
 * Divi 5's own `data_app_window` mechanism (see register_vb_assets() in
 * D5ModuleOpenstreetmap.php) — the global name is auto-generated by Divi
 * core itself from our script handle via `TextTransform::pascal_case()`,
 * not something we get to choose.
 *
 * We previously used our own separate `wp_localize_script()` calls on a
 * later, generic hook (`d5osmTranslations`, `d5osmCptTypes`,
 * `d5osmCptTaxonomies`, `d5osmCptPreview`) — confirmed via the Visual
 * Builder's own console that none of them ever actually reached `window`
 * in the app window, despite the exact same code working for `d5osm_vars`
 * on the (single-window) front-end. `data_app_window` is Divi's own
 * supported channel for handing data to a package build's app-window
 * script specifically (already used internally, e.g. the `divi-settings`
 * package), read synchronously by `PackageBuildManager::enqueue_scripts()`
 * right when it registers the script — no separate hook, no window
 * ambiguity.
 */
export function getBuilderData(): D5OsmBuilderData {
  return window.D5ModuleOpenstreetmapBuilderBundleScriptData ?? {};
}
